CREATE TEMP TABLE taxonomy_review_audit_observed ON COMMIT DROP AS
SELECT
  batch.product_id,
  batch.product_name AS expected_product_name,
  batch.current_category AS expected_current_category,
  batch.current_subcategory AS expected_current_subcategory,
  batch.final_category,
  batch.final_subcategory,
  product.id AS observed_product_id,
  product.name AS observed_product_name,
  current_category.name AS observed_category,
  current_subcategory.name AS observed_subcategory,
  current_subcategory.category_id AS observed_subcategory_category_id,
  product.category_id AS observed_category_id,
  product.subcategory_id AS observed_subcategory_id,
  product.classification_source,
  product.classification_confidence,
  target_category.category_count,
  target_pair.pair_count,
  CASE
    WHEN product.id IS NULL THEN 'missing_product'
    WHEN product.name IS DISTINCT FROM batch.product_name THEN 'product_name_mismatch'
    WHEN target_category.category_count <> 1 THEN 'target_category_missing_or_ambiguous'
    WHEN target_pair.pair_count <> 1 THEN 'target_pair_missing_or_ambiguous'
    WHEN current_category.name = batch.current_category
      AND current_subcategory.name = batch.current_subcategory
      AND current_subcategory.category_id = product.category_id
      THEN 'matches_original'
    WHEN current_category.name = batch.final_category
      AND current_subcategory.name = batch.final_subcategory
      AND current_subcategory.category_id = product.category_id
      THEN 'already_at_final'
    ELSE 'unexpected_classification'
  END AS audit_state
FROM catalog_taxonomy_review_batch AS batch
LEFT JOIN public.products AS product
  ON product.id = batch.product_id
LEFT JOIN public.categories AS current_category
  ON current_category.id = product.category_id
LEFT JOIN public.subcategories AS current_subcategory
  ON current_subcategory.id = product.subcategory_id
LEFT JOIN LATERAL (
  SELECT count(*)::integer AS category_count
  FROM public.categories AS category
  WHERE category.name = batch.final_category
) AS target_category ON true
LEFT JOIN LATERAL (
  SELECT count(*)::integer AS pair_count
  FROM public.categories AS category
  JOIN public.subcategories AS subcategory
    ON subcategory.category_id = category.id
  WHERE category.name = batch.final_category
    AND subcategory.name = batch.final_subcategory
) AS target_pair ON true;

SELECT
  current_database() AS database_name,
  current_user AS executed_as,
  current_setting('server_version') AS server_version,
  clock_timestamp() AS audited_at,
  (SELECT count(*) FROM taxonomy_review_audit_observed) AS expected_products;

SELECT
  audit_state,
  count(*)::bigint AS product_count,
  count(*) FILTER (
    WHERE classification_source IS DISTINCT FROM 'manual'
       OR classification_confidence IS DISTINCT FROM 'manual'
  )::bigint AS products_without_manual_markers
FROM taxonomy_review_audit_observed
GROUP BY audit_state
ORDER BY audit_state;

SELECT
  count(*)::bigint AS expected_products,
  count(*) FILTER (WHERE audit_state = 'matches_original')::bigint AS matches_original,
  count(*) FILTER (WHERE audit_state = 'already_at_final')::bigint AS already_at_final,
  count(*) FILTER (
    WHERE audit_state NOT IN ('matches_original', 'already_at_final')
  )::bigint AS unexpected_or_missing,
  count(*) FILTER (
    WHERE classification_source IS DISTINCT FROM 'manual'
       OR classification_confidence IS DISTINCT FROM 'manual'
  )::bigint AS products_without_manual_markers,
  count(*) FILTER (
    WHERE category_count <> 1 OR pair_count <> 1
  )::bigint AS products_with_missing_or_ambiguous_targets
FROM taxonomy_review_audit_observed;

SELECT
  expected_current_category,
  expected_current_subcategory,
  final_category,
  final_subcategory,
  audit_state,
  count(*)::bigint AS product_count
FROM taxonomy_review_audit_observed
GROUP BY
  expected_current_category,
  expected_current_subcategory,
  final_category,
  final_subcategory,
  audit_state
ORDER BY
  expected_current_category,
  expected_current_subcategory,
  final_category,
  final_subcategory,
  audit_state;

SELECT
  count(*) FILTER (WHERE product.category_id IS NULL)::bigint AS products_without_category,
  count(*) FILTER (
    WHERE product.category_id IS NOT NULL AND category.id IS NULL
  )::bigint AS products_with_missing_category_reference,
  count(*) FILTER (WHERE product.subcategory_id IS NULL)::bigint AS products_without_subcategory,
  count(*) FILTER (
    WHERE product.subcategory_id IS NOT NULL AND subcategory.id IS NULL
  )::bigint AS products_with_missing_subcategory_reference,
  count(*) FILTER (
    WHERE category.id IS NOT NULL
      AND subcategory.id IS NOT NULL
      AND subcategory.category_id IS DISTINCT FROM product.category_id
  )::bigint AS products_with_category_subcategory_mismatch,
  count(*) FILTER (
    WHERE product.category_id IS NULL
       OR category.id IS NULL
       OR product.subcategory_id IS NULL
       OR subcategory.id IS NULL
       OR subcategory.category_id IS DISTINCT FROM product.category_id
  )::bigint AS products_with_invalid_taxonomy_pair,
  (
    SELECT count(*)::bigint
    FROM (
      SELECT name
      FROM public.categories
      GROUP BY name
      HAVING count(*) > 1
    ) AS duplicate_categories
  ) AS duplicate_category_names,
  (
    SELECT count(*)::bigint
    FROM (
      SELECT category_id, name
      FROM public.subcategories
      GROUP BY category_id, name
      HAVING count(*) > 1
    ) AS duplicate_subcategories
  ) AS duplicate_subcategory_names_within_category
FROM public.products AS product
LEFT JOIN public.categories AS category
  ON category.id = product.category_id
LEFT JOIN public.subcategories AS subcategory
  ON subcategory.id = product.subcategory_id;

SELECT
  classification_source,
  classification_confidence,
  count(*)::bigint AS product_count
FROM public.products
GROUP BY classification_source, classification_confidence
ORDER BY classification_source NULLS FIRST, classification_confidence NULLS FIRST;

-- Export this row-level result before and after for a direct, product-by-product comparison.
SELECT
  product_id,
  expected_product_name,
  observed_product_name,
  audit_state,
  expected_current_category,
  expected_current_subcategory,
  observed_category,
  observed_subcategory,
  final_category,
  final_subcategory,
  classification_source,
  classification_confidence,
  category_count AS target_category_count,
  pair_count AS target_pair_count
FROM taxonomy_review_audit_observed
ORDER BY product_id;

ROLLBACK;
